import{_ as d,o as e,c as o,a2 as r}from"./chunks/framework.BzFiDlvK.js";const p=JSON.parse('{"title":"术语表","description":"","frontmatter":{},"headers":[],"relativePath":"glossary.md","filePath":"glossary.md"}'),c={name:"glossary.md"};function a(n,t,s,i,h,l){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="术语表" tabindex="-1">术语表 <a class="header-anchor" href="#术语表" aria-label="Permalink to &quot;术语表&quot;">​</a></h1><p>按主题分组。每个词给「中文 · English · 一句话解释」，最后有一张<strong>易混淆概念对照表</strong>。</p><hr><h2 id="语言与环境" tabindex="-1">语言与环境 <a class="header-anchor" href="#语言与环境" aria-label="Permalink to &quot;语言与环境&quot;">​</a></h2><table tabindex="0"><thead><tr><th>中文</th><th>English</th><th>说明</th></tr></thead><tbody><tr><td>解释型语言</td><td>interpreted language</td><td>源码由解释器逐句翻译并执行，不需要单独的编译步骤。Python 属于这一类</td></tr><tr><td>编译型语言</td><td>compiled language</td><td>先把源码整体编译成机器码，再执行。如 C/C++、Go</td></tr><tr><td>字节码</td><td>bytecode</td><td>源码被编译成的中间形式，由 Python 虚拟机执行</td></tr><tr><td>解释器</td><td>interpreter</td><td>执行 Python 代码的程序；<code>python3 -V</code> 查的就是它的版本</td></tr><tr><td>交互模式</td><td>interactive mode</td><td>解释器跑完不退出，停在 <code>&gt;&gt;&gt;</code> 等继续输入（<code>python3 -i x.py</code>）</td></tr><tr><td>非交互模式</td><td>non-interactive mode</td><td>从开始跑到结束，不中断（<code>python3 x.py</code>）</td></tr><tr><td>标准库</td><td>standard library</td><td>Python 自带的库，装了 Python 就能用，如 <code>os</code>、<code>json</code>、<code>re</code></td></tr><tr><td>第三方库</td><td>third-party library</td><td>需要额外 <code>pip install</code> 的库，如 <code>requests</code>、<code>pandas</code></td></tr></tbody></table><h2 id="基础语法" tabindex="-1">基础语法 <a class="header-anchor" href="#基础语法" aria-label="Permalink to &quot;基础语法&quot;">​</a></h2><table tabindex="0"><thead><tr><th>中文</th><th>English</th><th>说明</th></tr></thead><tbody><tr><td>变量</td><td>variable</td><td>给数据起的名字，随时可改指向</td></tr><tr><td>赋值</td><td>assignment</td><td><code>x = 1</code>，把右边给左边</td></tr><tr><td>数据类型</td><td>data type</td><td><code>int</code> / <code>float</code> / <code>str</code> / <code>list</code> / <code>tuple</code> / <code>dict</code> / <code>set</code></td></tr><tr><td>整数</td><td>integer (<code>int</code>)</td><td>不带小数点的数</td></tr><tr><td>浮点数</td><td>float</td><td>带小数点的数</td></tr><tr><td>字符串</td><td>string (<code>str</code>)</td><td>用引号包起来的一串字符</td></tr><tr><td>列表</td><td>list</td><td>有序、可变、用 <code>[]</code> 表示，如 <code>[1, 2, 3]</code></td></tr><tr><td>元组</td><td>tuple</td><td>有序、<strong>不可变</strong>、用 <code>()</code> 表示，如 <code>(1, 2, 3)</code></td></tr><tr><td>集合</td><td>set</td><td>无序、不重复，用 <code>{}</code> 或 <code>set()</code>，如 <code>{1, 2, 3}</code></td></tr><tr><td>字典</td><td>dictionary (<code>dict</code>)</td><td>键值对映射，用 <code>{}</code>，如 <code>{&quot;name&quot;: &quot;张三&quot;}</code></td></tr><tr><td>索引</td><td>index</td><td>取元素的位置，从 <strong>0</strong> 开始；负数表示从后往前</td></tr><tr><td>切片</td><td>slice</td><td><code>s[1:5:2]</code> 取一段</td></tr><tr><td>类型转换</td><td>type conversion / casting</td><td><code>int(&quot;123&quot;)</code>、<code>str(456)</code></td></tr><tr><td>注释</td><td>comment</td><td><code>#</code> 开头，给人看，不执行</td></tr><tr><td>关键字</td><td>keyword</td><td>语言保留字，不能当变量名，如 <code>if</code>、<code>for</code>、<code>class</code></td></tr><tr><td>命名规范</td><td>naming convention</td><td>变量用小写下划线（snake_case）</td></tr></tbody></table><h2 id="流程控制与函数" tabindex="-1">流程控制与函数 <a class="header-anchor" href="#流程控制与函数" aria-label="Permalink to &quot;流程控制与函数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>中文</th><th>English</th><th>说明</th></tr></thead><tbody><tr><td>条件判断</td><td>conditional</td><td><code>if</code> / <code>elif</code> / <code>else</code></td></tr><tr><td>模式匹配</td><td>pattern matching</td><td><code>match</code> / <code>case</code>（Python 3.10+）</td></tr><tr><td>循环</td><td>loop</td><td><code>while</code>（条件） / <code>for</code>（遍历）</td></tr><tr><td>循环嵌套</td><td>nested loop</td><td>循环里套循环</td></tr><tr><td>推导式</td><td>comprehension</td><td><code>[x for x in range(10)]</code></td></tr><tr><td>函数</td><td>function</td><td>用 <code>def</code> 定义，可重复调用的一段代码</td></tr><tr><td>参数</td><td>parameter / argument</td><td>形参是定义时的占位，实参是调用时传入的值</td></tr><tr><td>默认参数</td><td>default parameter</td><td>不传就用默认值的参数</td></tr><tr><td>可变参数</td><td><code>*args</code> / <code>**kwargs</code></td><td>参数个数不固定时用</td></tr><tr><td>返回值</td><td>return value</td><td><code>return</code> 把结果交回给调用方；没有 <code>return</code> 就返回 <code>None</code></td></tr><tr><td>作用域</td><td>scope</td><td>变量在哪个范围里可见</td></tr><tr><td>高阶函数</td><td>higher-order function</td><td>参数或返回值是函数的函数</td></tr><tr><td>装饰器</td><td>decorator</td><td><code>@xxx</code> 写在函数上一行，用来增强函数功能</td></tr></tbody></table><h2 id="面向对象与模块" tabindex="-1">面向对象与模块 <a class="header-anchor" href="#面向对象与模块" aria-label="Permalink to &quot;面向对象与模块&quot;">​</a></h2><table tabindex="0"><thead><tr><th>中文</th><th>English</th><th>说明</th></tr></thead><tbody><tr><td>类</td><td>class</td><td>用 <code>class</code> 定义，是「模板」</td></tr><tr><td>实例 / 对象</td><td>instance / object</td><td>由类创建出来的具体个体</td></tr><tr><td>方法</td><td>method</td><td>定义在类里的函数，<code>self</code> 是约定俗成的第一个参数</td></tr><tr><td>构造方法</td><td>constructor (<code>__init__</code>)</td><td>创建实例时自动调用，用来初始化属性</td></tr><tr><td>继承</td><td>inheritance</td><td>子类复用父类的属性和方法</td></tr><tr><td>魔术方法</td><td>magic method / dunder</td><td>形如 <code>__add__</code>、<code>__str__</code>，让对象支持运算符和内置函数</td></tr><tr><td>模块</td><td>module</td><td>一个 <code>.py</code> 文件就是一个模块</td></tr><tr><td>包</td><td>package</td><td>含 <code>__init__.py</code> 的目录，用来组织多个模块</td></tr><tr><td>导入</td><td>import</td><td><code>import math</code> / <code>from math import pi</code></td></tr></tbody></table><h2 id="异常与调试" tabindex="-1">异常与调试 <a class="header-anchor" href="#异常与调试" aria-label="Permalink to &quot;异常与调试&quot;">​</a></h2><table tabindex="0"><thead><tr><th>中文</th><th>English</th><th>说明</th></tr></thead><tbody><tr><td>异常</td><td>exception</td><td>运行期出错，如 <code>ZeroDivisionError</code></td></tr><tr><td>语法错误</td><td>syntax error</td><td>程序<strong>跑不起来</strong>，如少括号、多缩进</td></tr><tr><td>捕获异常</td><td>catch / handle exception</td><td><code>try ... except ...</code></td></tr><tr><td>抛出异常</td><td>raise</td><td>主动报错</td></tr><tr><td>自定义异常</td><td>custom exception</td><td>继承 <code>Exception</code> 定义业务异常</td></tr><tr><td>断点</td><td>breakpoint</td><td>程序在此暂停，<code>breakpoint()</code></td></tr><tr><td>调试器</td><td>debugger</td><td><code>pdb</code>；常用命令 <code>n</code> / <code>c</code> / <code>pp</code> / <code>break</code></td></tr></tbody></table><h2 id="项目实战" tabindex="-1">项目实战 <a class="header-anchor" href="#项目实战" aria-label="Permalink to &quot;项目实战&quot;">​</a></h2><table tabindex="0"><thead><tr><th>中文</th><th>English</th><th>说明</th></tr></thead><tbody><tr><td>网页抓取</td><td>web scraping</td><td>用 <code>requests</code> 拉页面，再用 <code>re</code> / <code>BeautifulSoup</code> 提取</td></tr><tr><td>正则表达式</td><td>regular expression (<code>re</code>)</td><td>匹配文本模式的「小语言」</td></tr><tr><td>数据框</td><td>DataFrame</td><td><code>pandas</code> 的核心结构，像带行列名的表格</td></tr><tr><td>虚拟环境</td><td>virtualenv / venv</td><td>给每个项目隔离一套依赖，避免版本打架</td></tr><tr><td>关系型数据库</td><td>relational database</td><td>用表和 SQL，如 MySQL / SQLite</td></tr><tr><td>NoSQL</td><td>NoSQL</td><td>非关系型，如 Redis（键值）、MongoDB（文档）</td></tr><tr><td>进程 / 线程</td><td>process / thread</td><td>并发的两种粒度；<code>multiprocessing</code> / <code>threading</code></td></tr><tr><td>多进程通信</td><td>IPC</td><td>进程间传数据，如 <code>Queue</code>、<code>Pipe</code></td></tr><tr><td>MVC</td><td>Model-View-Controller</td><td>Django 的架构划分：模型 / 视图模板 / 控制器</td></tr><tr><td>物联网</td><td>IoT</td><td>设备联网，如 ESP32 + MQTT</td></tr><tr><td>消息队列协议</td><td>MQTT</td><td>物联网常用的轻量发布/订阅协议</td></tr><tr><td>物模型</td><td>thing model</td><td>把设备抽象成「属性 + 事件 + 方法」的数据模板</td></tr></tbody></table><h2 id="进阶与常用库-第-10–15-章" tabindex="-1">进阶与常用库（第 10–15 章） <a class="header-anchor" href="#进阶与常用库-第-10–15-章" aria-label="Permalink to &quot;进阶与常用库（第 10–15 章）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>中文</th><th>English</th><th>说明</th></tr></thead><tbody><tr><td>具名元组</td><td><code>namedtuple</code></td><td><code>collections</code> 里带字段名的元组，比普通元组可读</td></tr><tr><td>双向队列</td><td><code>deque</code></td><td>两端都能 O(1) 进出的队列，支持 <code>maxlen</code></td></tr><tr><td>计数器</td><td><code>Counter</code></td><td><code>collections</code> 里数数的字典，<code>most_common()</code> 取高频项</td></tr><tr><td>默认值字典</td><td><code>defaultdict</code></td><td>取不存在的键时自动给默认值，不报 <code>KeyError</code></td></tr><tr><td>缓存装饰器</td><td><code>functools.lru_cache</code></td><td>把函数结果缓存起来，重复调用直接命中</td></tr><tr><td>上下文管理器</td><td>context manager</td><td>支持 <code>with</code> 语句的对象，进入/退出时自动执行</td></tr><tr><td>线程池</td><td><code>ThreadPoolExecutor</code></td><td>并发执行一批任务，适合 I/O 密集</td></tr><tr><td>多进程</td><td><code>multiprocessing</code></td><td>绕过 GIL 真并行，适合 CPU 密集</td></tr><tr><td>全局解释器锁</td><td>GIL</td><td>CPython 的互斥锁，导致多线程不能并行跑纯计算</td></tr><tr><td>Redis</td><td>Redis</td><td>内存键值数据库（NoSQL），常做缓存</td></tr><tr><td>关系型数据库</td><td>MySQL / SQLite</td><td>用表和 SQL 的数据库</td></tr><tr><td>对象关系映射</td><td>ORM</td><td>用 Python 类操作数据库表，Django 自带</td></tr><tr><td>数据迁移</td><td>migration</td><td>把模型改动同步到数据库表结构</td></tr><tr><td>模板引擎</td><td>template</td><td>把数据填进 HTML，Django 用 <code>{% %}</code> / <code>{{ }}</code></td></tr><tr><td>表格处理</td><td><code>openpyxl</code> / <code>python-docx</code></td><td>读写 <code>.xlsx</code> / <code>.docx</code>（<code>.xls</code> 旧格式要用 <code>xlrd</code>/<code>xlwt</code>）</td></tr><tr><td>数据框</td><td><code>pandas</code> / DataFrame</td><td>带行列名的二维表格数据结构</td></tr><tr><td>绘图</td><td><code>matplotlib</code></td><td>画折线图/柱状图，保存成 png</td></tr><tr><td>HTTP 请求库</td><td><code>requests</code></td><td>发网页请求，比标准库 <code>urllib</code> 好用</td></tr><tr><td>正则表达式</td><td><code>re</code></td><td>文本模式匹配，<code>findall</code> / <code>sub</code> / <code>split</code></td></tr><tr><td>JSON</td><td><code>json</code></td><td>与 <code>dict</code> 互转：<code>dumps</code> / <code>loads</code></td></tr><tr><td>人脸识别</td><td>face recognition</td><td>OpenCV 的 LBPH 识别器，需 <code>opencv-contrib-python</code></td></tr><tr><td>微控制器</td><td>ESP32</td><td>支持 Wi-Fi/蓝牙的开发板，可跑 MicroPython</td></tr><tr><td>MicroPython</td><td>MicroPython</td><td>跑在硬件上的精简版 Python</td></tr><tr><td>MQTT</td><td>MQTT</td><td>发布/订阅式消息协议，物联网常用</td></tr><tr><td>烧录</td><td>flash</td><td>把固件/程序写进开发板，用 <code>esptool.py</code></td></tr></tbody></table><hr><h2 id="易混淆概念对照" tabindex="-1">易混淆概念对照 <a class="header-anchor" href="#易混淆概念对照" aria-label="Permalink to &quot;易混淆概念对照&quot;">​</a></h2><table tabindex="0"><thead><tr><th>容易混</th><th>区别</th></tr></thead><tbody><tr><td><strong>列表 vs 元组</strong></td><td>列表可变（能改），元组不可变（不能改）；元组效率更高</td></tr><tr><td><strong>列表 vs 集合</strong></td><td>列表有序可重复，集合无序不重复</td></tr><tr><td><strong><code>=</code> vs <code>==</code></strong></td><td><code>=</code> 是赋值，<code>==</code> 是比较是否相等</td></tr><tr><td><strong><code>is</code> vs <code>==</code></strong></td><td><code>==</code> 比值，<code>is</code> 比是不是同一个对象（同一块内存）</td></tr><tr><td><strong><code>/</code> vs <code>//</code></strong></td><td><code>/</code> 除法得浮点，<code>//</code> 整除得整数</td></tr><tr><td><strong>可变对象作默认参数</strong></td><td><code>def f(x=[])</code> 是陷阱：默认值只在定义时创建一次，会被反复共用</td></tr><tr><td><strong>浅拷贝 vs 深拷贝</strong></td><td>浅拷贝只复制第一层，里层还是同一份；深拷贝递归复制</td></tr><tr><td><strong><code>import a</code> vs <code>from a import b</code></strong></td><td>前者用 <code>a.b</code> 访问，后者直接 <code>b</code></td></tr><tr><td><strong>语法错误 vs 异常</strong></td><td>语法错误在<strong>运行前</strong>就被拦下；异常在<strong>运行时</strong>才发生</td></tr><tr><td><strong>进程 vs 线程</strong></td><td>进程有独立内存，通信要 IPC；线程共享内存，但受 GIL 限制</td></tr><tr><td><strong><code>while</code> vs <code>for</code></strong></td><td><code>while</code> 条件成立就循环，<code>for</code> 遍历可迭代对象</td></tr><tr><td><strong><code>append</code> vs <code>extend</code></strong></td><td><code>append([4,5])</code> 把整个列表当一个元素加进去；<code>extend([4,5])</code> 逐个加</td></tr></tbody></table><hr><p><a href="/zero-basics-python/">返回总目录</a></p>',22)])])}const b=d(c,[["render",a]]);export{p as __pageData,b as default};
